import pytest
from billing.plans import (PLAN_ENTERPRISE, is_enterprise, is_known, parse_webhook)


def test_ac1_webhook_flips_enterprise():
    """AC1: Webhook triggers enterprise branch for real webhooks."""
    payload = "plan=enterprise&other=value"
    result = parse_webhook(payload)
    assert is_enterprise(result["plan"])


def test_ac2_shell_check_matches():
    """AC2: Pasted plan value matches by hand."""
    assert is_enterprise(PLAN_ENTERPRISE)


def test_ac3_equality_compare():
    """AC3: Plan string comparison uses equality, not identity."""
    assert is_enterprise(PLAN_ENTERPRISE) is True


def test_ac4_uncertainty_check():
    """AC4: Verification of the detection mechanism."""
    assert is_known(PLAN_ENTERPRISE)


def test_ac5_webhook_detection_works():
    """AC5: Webhook-driven plan detection works."""
    payload = "plan=enterprise"
    assert is_enterprise(parse_webhook(payload)["plan"])

