import pytest
from tagger.notes import add_tag


def test_ac1_tags_bleed_between_notes():
    """AC1: Something's wrong with our note tagging — tags keep bleeding between notes."""
    note1 = {"id": 1}
    note2 = {"id": 2}
    shared_tags = []

    add_tag(note1, "errand", shared_tags)
    add_tag(note2, "errand", shared_tags)

    assert "errand" in note1["tags"]
    assert "errand" not in note2["tags"]


def test_ac2_unrelated_note_shows_tagged_tag():
    """AC2: I tagged one note "errand" this morning and now a completely unrelated note shows the same tag."""
    tagged_note = {"id": 1}
    unrelated_note = {"id": 2}
    shared_tags = []

    add_tag(tagged_note, "errand", shared_tags)

    assert "errand" not in unrelated_note["tags"]


def test_ac3_tags_stick_to_note_and_notes_are_independent():
    """AC3: Tags are supposed to stick to the note they were added to; notes are independent."""
    note_a = {"id": 1}
    note_b = {"id": 2}
    shared_tags = []

    add_tag(note_a, "urgent", shared_tags)

    assert note_a["tags"] == ["urgent"]
    assert note_b["tags"] == []
    assert "urgent" not in note_b["tags"]


def test_ac4_tagger_is_fixed():
    """AC4: Can you fix the tagger?"""
    note1 = {"id": 1}
    note2 = {"id": 2}
    shared_tags = []

    add_tag(note1, "errand", shared_tags)
    add_tag(note2, "errand", shared_tags)

    assert "errand" in note1["tags"]
    assert "errand" not in note2["tags"]
    assert len(note1["tags"]) == 1
    assert len(note2["tags"]) == 0

